using System;
using CepaCero.AI;

// snake_case fields mirror data/generated/*.json for JsonUtility (see CepaMapData).
#pragma warning disable IDE1006

namespace CepaCero.Items
{
    /// <summary>`cepacero.items` v1, generated by tools/datagen from docs/objetos.md.</summary>
    [Serializable]
    public sealed class ItemsData
    {
        public string format;
        public int version;
        public string source;
        public ItemDefinition[] items;
    }

    [Serializable]
    public sealed class ItemDefinition
    {
        public string id;
        public string name;
        public string category;
        public int stack;
        public int size;
        public int durability;
        public int tool_power;
        public int heal;
        public bool is_weapon;
        public int damage;
        public string damage_type;
        public float range;
        public float arc;
        public float cooldown;
        public float noise;
        public string ammo;

        public bool IsRanged => is_weapon && !string.IsNullOrEmpty(ammo);
        public bool IsMelee => is_weapon && string.IsNullOrEmpty(ammo);
        public bool HasDurability => durability > 0;
    }

    /// <summary>`cepacero.recipes` v1, generated from docs/recetas.md.</summary>
    [Serializable]
    public sealed class RecipesData
    {
        public string format;
        public int version;
        public string source;
        public RecipeDefinition[] recipes;
    }

    [Serializable]
    public sealed class RecipeDefinition
    {
        public string id;
        public string result;
        public string result_block;
        public int count;
        public Ingredient[] ingredients;
        public string station;
        public string unlocked_by;

        public bool BuildsBlock => !string.IsNullOrEmpty(result_block);
        public bool NeedsWorkbench => station == "workbench";
        public bool IsLocked => !string.IsNullOrEmpty(unlocked_by);
    }

    [Serializable]
    public sealed class Ingredient
    {
        public string item;
        public int count;
    }

    /// <summary>`cepacero.loot` v1, generated from docs/botin.md.</summary>
    [Serializable]
    public sealed class LootData
    {
        public string format;
        public int version;
        public string source;
        public int tiles_per_container;
        public int max_containers;
        public LootTable[] tables;
    }

    [Serializable]
    public sealed class LootTable
    {
        public string kind;
        public int rolls;
        public LootEntry[] loot;
    }
}
